// An OBD answer's data bytes to the value; false when too short.
inline bool obdValue(const Entry& e, const unsigned char* d, unsigned n, double* out) {
    if (e.source != kObd || n < e.bytes) {
        return false;
    }
    const double A = d[0], AB = e.bytes >= 2 ? d[0] * 256.0 + d[1] : d[0];
    switch (e.formula) {
        case 0:
            *out = A * e.a;
            return true;
        case 1:
            *out = A + e.b;
            return true;
        case 2:
            *out = A * e.a + e.b;
            return true;
        case 3:
            *out = AB * e.a;
            return true;
        case 4:
            *out = AB * e.a + e.b;
            return true;
        default:
            return false;
    }
}

